// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketValue) internal {
        ticketValue = bound(ticketValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketValue = 10;
        vm.assume(address(this).balance >= ticketValue);
        try c.play{value: ticketValue}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint contractBal = address(c).balance;
        assertTrue(potAfter == 0 || potAfter == 10 || contractBal >= potAfter);
    }

    function testFuzz_run(uint256 ticketValue) public {
        _run(ticketValue);
    }

    receive() external payable {}
}
